head.script:

	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};
    scwin.trigger1_onclick = function(e) {
        inputCalendar1.setDisabled(true);
    };
    scwin.trigger2_onclick = function(e) {
        inputCalendar1.setDisabled(false);

        /*
calendarImage="http://static.naver.net/green/v2/img/btn_security2_on.gif"
        calendarImageOver="http://static.naver.net/green/v2/img/btn_security2_off.gif"
        */
    };


	 scwin.checkVal = function() {
		return document.getElementsByClassName('w2calendar_go_today')[0].classList.contains('w2calendar_go_today_hidden');;
	}		
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
